  tools.exec_command({cmd:"cat .mocharc.json 2>/dev/null",workdir:"/app",max_output_tokens:1000}),
  tools.exec_command({cmd:"cat .mocharc.yml 2>/dev/null",workdir:"/app",max_output_tokens:1000}),
